head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > E > onmodelchange]<br/>set(), setEmptyValue() 메소드 또는 사용자의 입력으로 Key 의 값(Value)이 변경된 후 발생합니다.",
    "validation" : [
        "set(), setEmptyValue() 메소드 또는 사용자의 입력으로 Key 의 값(Value)이 변경된 후 발생합니다.",
        "변경 전/후 값(데이터형 포함)이 동일한 경우 onmodelchange 이벤트는 발생하지 않습니다.",
        "info 파라미터로 Key 의 ID 와 변경 전/후 값을 객체로 전달합니다.",
        "info.key 파라미터로 값(Value)이 변경된 Key 의 ID 값을 갖습니다.",
        "info.oldValue 파라미터로 변경되기 이전의 값(Value)을 갖습니다.",
        "info.newValue 파라미터로 변경된 후의 값(Value)을 갖습니다.",        
        "onmodelchange 이벤트에서 해당 Key 의 값(Value)을 조회하면 변경된 값(Value)이 반환됩니다.",
        "setEmptyValue() 메소드 실행 시 Key 의 갯수만큼 onmodelchange 이벤트가 발생합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {      
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }  

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);  

    // target 생성
    $c.gcm.createBasicDataMap();

    // event 바인딩    
    target1.bind("onmodelchange", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmodelchange=====");
        wf_body_bottom.getObj("scwin").setReturnValue("info: " + info);
        wf_body_bottom.getObj("scwin").setReturnValue("info.key: " + info.key);
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue: " + info.oldValue);
        wf_body_bottom.getObj("scwin").setReturnValue("info.newValue: " + info.newValue);
    });    

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');  
}   



scwin.btn_set_onclick = function (e) {   
    target1.set("key1", "stringValue");
};



scwin.btn_setEmptyValue_onclick = function (e) {   
    target1.setEmptyValue();
};
